class Student:
    def __init__(self, name):
        self.name = name
        self.grades = {}                 # a new dictionary for every student

    def add_grade(self, subject, mark):
        if not 0 <= mark <= 100:
            raise ValueError("Mark must be between 0 and 100")
        self.grades[subject] = mark

    def average(self):
        if not self.grades:
            return 0
        return round(sum(self.grades.values()) / len(self.grades), 2)

    def best_subject(self):
        if not self.grades:
            return None
        return max(self.grades, key=self.grades.get)     # max keeps the first of equal values
